#ifndef MELEE_TM_HOOK_H
#define MELEE_TM_HOOK_H

#include <Runtime/platform.h>

/**
 * Register state handed to an `inject` hook target.
 *
 * An `inject` hook (see docs/ai/overlay-build.md) replaces one vanilla
 * instruction with a branch to a trampoline generated by
 * tools/overlay_link.py. The trampoline saves these registers, calls
 * `void target(TmRegs* regs)`, restores them (so edits made by the target
 * take effect), runs the displaced instruction and resumes vanilla code.
 *
 * The layout must match INJECT_FRAME / inject_trampoline() in that tool.
 * r1, r2 and r13 are not saved; r1 at the hook site is `(u8*) regs + 0x108`.
 */
typedef struct TmRegs {
    /* +00 */ u32 r0;
    /* +04 */ u32 lr;
    /* +08 */ u32 cr;
    /* +0C */ u32 ctr;
    /* +10 */ u32 xer;
    /* +14 */ u32 pad_14;
    /* +18 */ u32 r[29]; ///< r3..r31; use #TM_REG
    /* +8C */ u32 pad_8C;
    /* +90 */ f64 f[14]; ///< f0..f13
} TmRegs;

/// Access general register @p n (3..31) of a #TmRegs pointer.
#define TM_REG(regs, n) ((regs)->r[(n) - 3])

#endif
